    this.addCommand(129 /* Set */, this.handleSet.bind(this));
    this.addCommand(132 /* Delete */, this.handleDelete.bind(this));
    this.addCommand(130 /* ListKeys */, this.handleListKeys.bind(this));
    this.addCommand(131 /* List */, this.handleList.bind(this));
    this.addCommand(133 /* Clear */, this.handleClear.bind(this));
