// src/servers/vibrationmotorserver.ts
var _VibrationMotorServer = class extends JDServiceServer {
  constructor(options) {
    super(SRV_VIBRATION_MOTOR, options);
    this._animationStep = -1;
    const { maxVibrations = 10 } = options || {};
    this.maxVibrations = this.addRegister(
      384 /* MaxVibrations */,
      [maxVibrations]
    );
    this.addCommand(
      128 /* Vibrate */,
      this.handleVibrate.bind(this)
    );
    this.on(REFRESH, this.handleRefresh.bind(this));
  }
  handleRefresh() {
    if (!this._animation)
      return;
    const { start, pattern } = this._animation;
    const now = this.device.bus.timestamp;
    const elapsed = now - start;
    let t = 0;
    for (let i = 0; i < pattern.length; ++i) {
      const [duration, speed] = pattern[i];
      const dt = duration << 3;
      t += dt;
      if (t - dt <= elapsed && t > elapsed) {
        if (this._animationStep !== i) {
          this._animationStep = i;
          this.emit(_VibrationMotorServer.VIBRATE_PATTERN, {
            duration,
            speed
          });
        }
        break;
      }
    }
    if (elapsed > t) {
      this._animation = void 0;
      this._animationStep = -1;
      this.emit(_VibrationMotorServer.VIBRATE_PATTERN, {
        duration: 0,
        speed: 0
      });
      this.emit(CHANGE);
    }
  }
  handleVibrate(pkt) {
    const [pattern] = pkt.jdunpack("r: u8 u0.8");
    this._animation = {
      start: this.device.bus.timestamp,
      pattern
    };
    this._animationStep = -1;
    if (pattern.length) {
      const [duration, speed] = pattern[0];
      this._animationStep = 0;
      this.emit(_VibrationMotorServer.VIBRATE_PATTERN, {
        duration,
        speed
      });
    }
    this.emit(CHANGE);
  }
};
