    this.addCommand(130 /* Reconnect */, this.handleReconnect.bind(this));
    this.addCommand(
      128 /* LastScanResults */,
      this.handleLastScanResults.bind(this)
    );
    this.addCommand(
      135 /* ListKnownNetworks */,
      this.handleListKnownNetworks.bind(this)
    );
    this.addCommand(129 /* AddNetwork */, this.handleAddNetwork.bind(this));
    this.addCommand(
      132 /* ForgetAllNetworks */,
      this.handleForgetAllNetworks.bind(this)
    );
    this.addCommand(
      131 /* ForgetNetwork */,
      this.handleForgetNetwork.bind(this)
    );
    this.addCommand(
      133 /* SetNetworkPriority */,
      this.handleSetNetworkPriority.bind(this)
    );
