// src/servers/planarpositionserver.ts
var PlanarPositionServer = class extends SensorServer {
  constructor() {
    super(SRV_PLANAR_POSITION, {
      readingValues: [0, 0],
      preferredStreamingInterval: 500
    });
  }
  move(dx, dy) {
    if (!dx && !dy)
      return;
    let [x = 0, y = 0] = this.reading.values();
    x += dx;
    y += dy;
    this.reading.setValues([x, y]);
    this.reading.sendGetAsync();
  }
};

