var WallClockScheduler = class {
  constructor() {
    this._now = typeof performance !== "undefined" ? () => performance.now() : () => Date.now();
    this._startTime = this._now();
  }
  get timestamp() {
    return this._now() - this._startTime;
  }
  resetTime(delta = 0) {
    this._startTime = this._now() - delta;
  }
  setTimeout(handler, delay2, ...args) {
    return setTimeout(handler, delay2, args);
  }
  clearTimeout(handle) {
    clearTimeout(handle);
  }
  setInterval(handler, delay2, ...args) {
    return setInterval(handler, delay2, args);
  }
  clearInterval(handle) {
    clearInterval(handle);
  }
};

